import React, { useState, useEffect } from 'react';
import { Card, Button, Alert, api } from '../App';

// ── Single Upload Box ────────────────────────────────────────────────────────
const UploadBox = ({ title, color, onUpload, loading, result }) => {
  const [file, setFile] = useState(null);
  const [drag, setDrag] = useState(false);

  const handleFile = f => {
    if (!f) return;
    const ext = f.name.split('.').pop().toLowerCase();
    if (!['xlsx','xls','csv'].includes(ext)) { alert('Only .xlsx / .xls / .csv'); return; }
    setFile(f);
  };

  const doUpload = () => { if (file) { onUpload(file); } };

  return (
    <div style={{ flex: 1, border: `2px solid ${drag ? color : '#e2e8f0'}`, borderRadius: 10, padding: 16, background: '#fff', transition: 'border 0.2s' }}>
      <div style={{ borderLeft: `4px solid ${color}`, paddingLeft: 10, marginBottom: 12 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: '#1a2533' }}>{title}</div>
      </div>

      {/* Drop zone */}
      <div
        onDragOver={e => { e.preventDefault(); setDrag(true); }}
        onDragLeave={() => setDrag(false)}
        onDrop={e => { e.preventDefault(); setDrag(false); handleFile(e.dataTransfer.files[0]); }}
        onClick={() => document.getElementById(`fu-${title.replace(/\s/g,'')}`).click()}
        style={{ border: '2px dashed #cbd5e0', borderRadius: 8, padding: '18px 12px', textAlign: 'center', cursor: 'pointer', background: drag ? '#f0f8ff' : '#fafbfc', marginBottom: 10 }}>
        <input id={`fu-${title.replace(/\s/g,'')}`} type="file" accept=".xlsx,.xls,.csv" style={{ display: 'none' }}
          onChange={e => handleFile(e.target.files[0])} />
        {file
          ? <><div style={{ fontSize: 22 }}>📄</div><div style={{ fontSize: 12, fontWeight: 600, color: '#333', marginTop: 4 }}>{file.name}</div></>
          : <><div style={{ fontSize: 26 }}>📥</div><div style={{ fontSize: 12, color: '#888', marginTop: 4 }}>Drop or <b style={{ color }}>browse</b></div></>
        }
      </div>

      {/* Result */}
      {result && (
        <div style={{ fontSize: 12, padding: '6px 10px', borderRadius: 6, marginBottom: 8,
          background: result.error ? '#fee2e2' : '#f0fdf4',
          color: result.error ? '#991b1b' : '#166534' }}>
          {result.error
            ? `❌ ${result.error}`
            : `✅ ${result.imported} imported · ${result.skipped} skipped${result.sale_no ? ` · Sale #${result.sale_no}` : ''}`
          }
          {result.errors?.length > 0 && result.errors.slice(0,2).map((e,i) => <div key={i} style={{ fontSize:11, marginTop:2 }}>• {e}</div>)}
        </div>
      )}

      <div style={{ display: 'flex', gap: 8 }}>
        <Button onClick={doUpload} disabled={!file || loading} variant="primary" style={{ flex: 1, background: color, fontSize: 12 }}>
          {loading ? 'Uploading…' : `⬆ Upload`}
        </Button>
        {file && <Button onClick={() => setFile(null)} variant="outline" size="sm" style={{ fontSize: 11 }}>Clear</Button>}
      </div>
    </div>
  );
};

// ── Main Import Page ─────────────────────────────────────────────────────────
export default function ImportPage() {
  const [catResult,   setCatResult]   = useState(null);
  const [soldResult,  setSoldResult]  = useState(null);
  const [catLoading,  setCatLoading]  = useState(false);
  const [soldLoading, setSoldLoading] = useState(false);
  const [merged,      setMerged]      = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [gradeFilter, setGradeFilter] = useState('');
  const [markFilter,  setMarkFilter]  = useState('');
  const [search,      setSearch]      = useState('');

  const loadSaleNos = () =>
    api.get('/import/sale-numbers')
       .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
       .catch(() => {});

  useEffect(() => { loadSaleNos(); }, []);

  useEffect(() => {
    if (!selSale) return;
    api.get(`/catalogue/merged?sale_no=${selSale}`).then(r => setMerged(r.data)).catch(() => {});
  }, [selSale]);

  const reloadMerged = (saleNo) => {
    const s = saleNo || selSale;
    if (s) api.get(`/catalogue/merged?sale_no=${s}`).then(r => setMerged(r.data)).catch(() => {});
  };

  const uploadCat = async (file) => {
    setCatLoading(true);
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await api.post('/import/catalogue', fd);
      setCatResult(r.data);
      loadSaleNos();
      if (r.data.sale_no) { setSelSale(String(r.data.sale_no)); reloadMerged(r.data.sale_no); }
    } catch (e) { setCatResult({ error: e.response?.data?.error || e.message }); }
    finally { setCatLoading(false); }
  };

  const uploadSold = async (file) => {
    setSoldLoading(true);
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await api.post('/import/sold-list', fd);
      setSoldResult(r.data);
      reloadMerged();
    } catch (e) { setSoldResult({ error: e.response?.data?.error || e.message }); }
    finally { setSoldLoading(false); }
  };

  // Unique filter values from merged data
  const grades = [...new Set(merged.map(r => r.grade).filter(Boolean))].sort();
  const marks  = [...new Set(merged.map(r => r.garden).filter(Boolean))].sort();

  const filtered = merged.filter(r =>
    (!gradeFilter || r.grade  === gradeFilter) &&
    (!markFilter  || r.garden === markFilter) &&
    (!search || (r.garden||'').toLowerCase().includes(search.toLowerCase()) || (r.origin||'').toLowerCase().includes(search.toLowerCase()))
  );

  const fmtPrice = (min, max) => {
    if (!min && !max) return <span style={{ color: '#ccc' }}>—</span>;
    if (min && max && Math.abs(parseFloat(min) - parseFloat(max)) > 0.5)
      return <span style={{ fontWeight: 700, color: '#1a3c5e' }}>₹{Number(min).toFixed(0)} – ₹{Number(max).toFixed(0)}</span>;
    const v = min || max;
    return <span style={{ fontWeight: 700, color: '#1a3c5e' }}>₹{Number(v).toFixed(0)}</span>;
  };

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>📥 Import Files</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Upload Catalogue and Sold List together. Table below shows merged data with Min–Max price from Sold List.</p>

      {/* ── Both upload boxes side by side ── */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 20 }}>
        <UploadBox title="📘 Catalogue Sheet"
          color="#1a3c5e"
          onUpload={uploadCat}
          loading={catLoading}
          result={catResult} />
        <UploadBox title="📗 Sold List"
          color="#1a7a4a"
          onUpload={uploadSold}
          loading={soldLoading}
          result={soldResult} />
      </div>

      {/* ── Merged data table ── */}
      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, flexWrap: 'wrap', gap: 10 }}>
          <div>
            <h3 style={{ fontSize: 15, marginBottom: 2 }}>📋 Catalogue + Sold List (Merged)</h3>
            {merged.length > 0 && <div style={{ fontSize: 12, color: '#888' }}>Showing {filtered.length} of {merged.length} lots</div>}
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
            {/* Sale selector */}
            {saleNos.length > 0 && (
              <select value={selSale} onChange={e => setSelSale(e.target.value)}
                style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
              </select>
            )}
            <select value={gradeFilter} onChange={e => setGradeFilter(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={markFilter} onChange={e => setMarkFilter(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
              <option value="">All Marks</option>
              {marks.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, width: 130 }} />
            {(gradeFilter || markFilter || search) && (
              <Button size="sm" variant="outline" onClick={() => { setGradeFilter(''); setMarkFilter(''); setSearch(''); }}>Clear</Button>
            )}
          </div>
        </div>

        {filtered.length === 0
          ? <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>
              {selSale ? 'No data. Upload Catalogue first.' : 'Select a sale number above.'}
            </div>
          : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ background: '#1a3c5e', color: '#fff' }}>
                    {['Sale No','Lot No','Garden (Mark)','Origin (Location)','Grade','Bags','Net Wt','Min–Max Price ₹','Broker'].map(h => (
                      <th key={h} style={{ padding: '8px 10px', textAlign: 'left', fontWeight: 600, whiteSpace: 'nowrap' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filtered.slice(0, 500).map((row, i) => (
                    <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                      <td style={{ padding: '6px 10px', fontWeight: 600 }}>{row.sale_no}</td>
                      <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                      <td style={{ padding: '6px 10px', fontWeight: 700, color: '#1a3c5e' }}>{row.garden}</td>
                      <td style={{ padding: '6px 10px', fontSize: 11, color: '#777' }}>{row.origin || '—'}</td>
                      <td style={{ padding: '6px 10px' }}>
                        <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                      </td>
                      <td style={{ padding: '6px 10px' }}>{row.bags || '—'}</td>
                      <td style={{ padding: '6px 10px' }}>{row.net_wt || '—'}</td>
                      <td style={{ padding: '6px 10px' }}>{fmtPrice(row.min_deal_price, row.max_deal_price)}</td>
                      <td style={{ padding: '6px 10px', color: '#888', fontSize: 11 }}>{row.broker || '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filtered.length > 500 && (
                <div style={{ padding: 10, textAlign: 'center', color: '#888', fontSize: 12 }}>Showing 500 of {filtered.length}. Use filters to narrow.</div>
              )}
            </div>
          )
        }
      </Card>
    </div>
  );
}
